import fs from 'fs';
import path from 'path';
import { __dist, __root } from './configProvider';
import { MASHUP_DETAILS, MASHUP_NAME } from './constants';
import archiver from 'archiver';

const extensionFilename = `${MASHUP_NAME}.zip`;
const qextFilename = `${MASHUP_NAME}.qext`;
const wblFilename = 'wbfolder.wbl';

const extensionPath = path.resolve(__root, extensionFilename);

const getAllFiles = function (dirPath, arrayOfFiles: string[] = []) {
  const files = fs.readdirSync(dirPath, { withFileTypes: true });
  arrayOfFiles = arrayOfFiles ?? [];

  files.forEach((file) => {
    if (file.isDirectory()) {
      arrayOfFiles = getAllFiles(path.resolve(dirPath, file.name), arrayOfFiles);
    } else {
      arrayOfFiles.push(file.name);
    }
  });
  return arrayOfFiles;
};

export async function packExtension(): Promise<void> {
  return new Promise((resolve, reject) => {
    try {
      MASHUP_DETAILS.version = '0.1.0.0';

      const qextFile = fs.openSync(path.resolve(__dist, qextFilename), 'w');
      fs.writeSync(qextFile, JSON.stringify(MASHUP_DETAILS));

      const filesArr = getAllFiles(__dist);
      const wblFile = fs.openSync(path.resolve(__dist, wblFilename), 'w');
      fs.writeSync(wblFile, filesArr.join(';\n'));

      const extZipStream = fs.createWriteStream(extensionPath);
      extZipStream.on('close', () => {
        console.log('Extension saved');
        resolve();
      });

      const extension = archiver('zip', { zlib: { level: 9 } });
      extension.on('error', (err) => {
        throw err;
      });
      extension.pipe(extZipStream);
      extension.directory(__dist, false);

      extension.finalize();
    } catch (ex) {
      console.error('Creating extension file failed.', ex);
      reject(ex);
    }
  });
}
